 CREATE OR REPLACE FUNCTION public.qnetrpt_ccassessmentdetail_prc(p_begindate timestamp without time zone, p_enddate timestamp without time zone)                                                                                                 
  RETURNS TABLE(seqno bigint, assessmentid uuid, objectid uuid, objectname character varying, name text, assessmentstatustypekey character varying, servicerequestnumber character varying, datype character varying, dasubtype character varying)
  LANGUAGE plpgsql                                                                                                                                                                                                                                
 AS $function$                                                                                                                                                                                                                                    
 BEGIN                                                                                                                                                                                                                                            
         -- SET NOCOUNT ON added to prevent extra result sets from                                                                                                                                                                                
         -- interfering with SELECT statements.                                                                                                                                                                                                   
                                                                                                                                                                                                                                                  
     --SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;                                                                                                                                                                                          
                                                                                                                                                                                                                                                  
     RETURN QUERY                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                  
     SELECT ROW_NUMBER() OVER (ORDER BY asmtd.AssessmentDetailId) AS SeqNo, asmt.AssessmentId, asmt.ObjectId, asmt.ObjectName,                                                                                                                    
     asmtt.Name, asmt.AssessmentStatusTypeKey,                                                                                                                                                                                                    
         INSR.ServiceRequestNumber,ISRT.Description as DAType,SRST.Description as DASubType --, nref.value('@Name', 'varchar(256)') QuestionName, nref1.value('@Value', 'varchar(256)') Answer                                                    
         FROM  Assessment asmt                                                                                                                                                                                                                    
               LEFT JOIN AssessmentTemplate ASMTT ON ASMTT.AssessmentTemplateId = ASMT.AssessmentTemplateId                                                                                                                                       
           LEFT JOIN AssessmentDetail asmtd ON asmt.AssessmentId = asmtd.AssessmentId                                                                                                                                                             
           INNER JOIN IntakeServiceRequest INSR ON INSR.IntakeServiceId = asmt.ObjectId                                                                                                                                                           
           INNER JOIN IntakeServiceRequestType ISRT ON ISRT.IntakeServReqTypeId = INSR.IntakeServReqTypeId                                                                                                                                        
           INNER JOIN ServiceRequestSubType SRST ON SRST.ServiceRequestSubTypeId = INSR.IntakeServiceRequestClassId                                                                                                                               
           where  CAST(INSR.Insertedon AS DATE) BETWEEN p_BeginDate AND p_EndDate;                                                                                                                                                                
           --CROSS APPLY AssessmentXml.nodes('//root//Asmt//Page//Section//Question') AS R(nref)                                                                                                                                                  
             --  OUTER APPLY AssessmentXml.nodes('//root//Asmt//Page//Section//Question//Field') AS P(nref1)                                                                                                                                      
     --WHERE INSR.ServiceRequestNumber = p_ServiceRequestNumber ;                                                                                                                                                                                 
 END;                                                                                                                                                                                                                                             
 $function$                                                                                                                                                                                                                                       

